2. Create DTOs/Common/. Files:
   DCDSS/DTOs/Common/PagedResult.cs — namespace DCDSS.DTOs.Common: public class PagedResult<T> { public IList<T> Items { get; set; } = []; public int Total { get; set; } public int Page { get; set; } public int PageSize { get; set; } }
   DCDSS/DTOs/Common/IAuditableResult.cs — namespace DCDSS.DTOs.Common: public interface IAuditableResult { int? EntityId { get; } }

4. Create DTOs/MedicalRecords/. Namespace DCDSS.DTOs.MedicalRecords. Files:
   CreateMedicalRecordDto.cs: int PatientId [Required]; int DoctorId [Required]; string Diagnosis [Required, MaxLength(500)]; string? TreatmentNotes [MaxLength(2000)]; DateTime VisitDate [Required].
   MedicalRecordDto.cs: int RecordId; int PatientId; int DoctorId; string? DoctorName; string Diagnosis; string? TreatmentNotes; DateTime VisitDate; string Status; IList<LabResultDto> LabResults; IList<MedicationDto> Medications. Implements IAuditableResult: int? EntityId => RecordId. NOTE: LabResultDto and MedicationDto are in their respective namespaces — import them via using DCDSS.DTOs.Laboratory; using DCDSS.DTOs.Medications;

14. Create Configuration/ typed settings and validator. Namespace DCDSS.Configuration. Files:
    JwtSettings.cs: public class JwtSettings { public string Issuer { get; set; } = ""; public string Audience { get; set; } = ""; public string SigningKey { get; set; } = ""; public int ExpiryMinutes { get; set; } = 60; }
    CorsSettings.cs: public class CorsSettings { public string AllowedOrigins { get; set; } = ""; }
    AdminSeedSettings.cs: public class AdminSeedSettings { public string Username { get; set; } = "admin"; public string Password { get; set; } = ""; public string FullName { get; set; } = ""; public string Email { get; set; } = ""; public string? Department { get; set; } }
    JwtSettingsValidator.cs: public class JwtSettingsValidator : IValidateOptions<JwtSettings>. Method ValidateOptions(string? name, JwtSettings options): if string.IsNullOrWhiteSpace(options.SigningKey) || options.SigningKey == "REPLACE_ME" || System.Text.Encoding.UTF8.GetByteCount(options.SigningKey) < 32 → return ValidateOptionsResult.Fail("JwtSettings:SigningKey must be at least 32 UTF-8 bytes and must not be the placeholder 'REPLACE_ME'."); return ValidateOptionsResult.Success;
